<?php
namespace App\Http\Controllers\Api;
use App\Enums\UserRole; use App\Http\Controllers\Controller; use App\Http\Requests\CancelAppointmentRequest; use App\Http\Requests\RescheduleAppointmentRequest; use App\Http\Requests\StoreAppointmentRequest; use App\Models\Appointment; use App\Models\Provider; use App\Models\Service; use App\Services\AppointmentLifecycleService; use App\Services\BookingService; use App\Support\ApiPresenter; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
class AppointmentController extends Controller { public function index(Request $request): JsonResponse {$q=Appointment::with('payment')->latest('starts_at');$u=$request->user();if($u->role===UserRole::Provider){$q->where('provider_id',$u->provider?->id ?? 0);}elseif($u->role!==UserRole::Admin){$q->where('user_id',$u->id);} $p=$q->paginate(20);return response()->json(['data'=>$p->getCollection()->map(fn($a)=>ApiPresenter::appointment($a))->values(),'meta'=>['current_page'=>$p->currentPage(),'last_page'=>$p->lastPage(),'total'=>$p->total()]]);} public function show(Request $request,Appointment $appointment): JsonResponse {$this->authorize('view',$appointment);return response()->json(['data'=>ApiPresenter::appointment($appointment->load('payment'))]);} public function store(StoreAppointmentRequest $request,BookingService $booking): JsonResponse {$provider=Provider::findOrFail($request->validated('provider_id'));$service=Service::findOrFail($request->validated('service_id'));$appointment=$booking->book($request->user(),$provider,$service,$request->validated('starts_at'),$request->header('Idempotency-Key'));return response()->json(['data'=>ApiPresenter::appointment($appointment)],201);} public function cancel(CancelAppointmentRequest $request,Appointment $appointment,AppointmentLifecycleService $lifecycle): JsonResponse {$this->authorize('cancel',$appointment);return response()->json(['data'=>ApiPresenter::appointment($lifecycle->cancel($appointment->load('payment'),$request->validated('reason')))]);} public function reschedule(RescheduleAppointmentRequest $request,Appointment $appointment,AppointmentLifecycleService $lifecycle): JsonResponse {$this->authorize('reschedule',$appointment);return response()->json(['data'=>ApiPresenter::appointment($lifecycle->reschedule($appointment,$request->validated('starts_at')))]);} }
